  "schema_version": 2,
  "scenarios": [
    {
      "id": "g-greeting",
      "user_message": "Hello, what can you help me with?",
      "reference_response": "Hello! I can assist you with a variety of tasks. How can I help you today?",
      "context": null,
      "expected_traits": ["on_topic", "safe", "format_correct"],
      "expected_tool_calls": null
    },
    {
