using System.Text.Json;

namespace MyApp.Evals.Tests;

internal static class Thresholds
{
    private static readonly ThresholdConfig s_config = Load();

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        if (!s_config.HardFail) return;

        foreach (var metric in result.Metrics)
        {
            if (s_config.ThresholdMap.TryGetValue(metric.Key, out var threshold))
            {
                if (metric.Value is NumericMetric nm && threshold.MinValue.HasValue)
                {
                    if (nm.Value < threshold.MinValue.Value)
                        Assert.Fail($"[{scenarioId}] {metric.Key} = {nm.Value} < min {threshold.MinValue.Value}");
                }
            }
        }
    }

    private static ThresholdConfig Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return new ThresholdConfig(false, new());
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<ThresholdConfig>(json, new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
            PropertyNameCaseInsensitive = true,
        }) ?? new ThresholdConfig(false, new());
    }
}

internal record ThresholdConfig(bool HardFail, Dictionary<string, ThresholdEntry> ThresholdMap);

internal record ThresholdEntry(double? MinValue, double? MaxValue, string? MinRating);

