using System.ClientModel;
using Azure.AI.OpenAI;
using OpenAI;

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (`dotnet test`), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        var connStr = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost " +
                "populates this at runtime, but `dotnet test` runs standalone. " +
                "Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential — works when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).\n" +
                "Get the exact endpoint from `azd env get-values` or " +
                "`az cognitiveservices account show -n <name> -g <rg> --query properties.endpoints`.");
        }

        // Parse connection string: Endpoint=...;Key=...;DeploymentId=...
        var parts = ParseConnectionString(connStr);
        var endpoint = parts.GetValueOrDefault("Endpoint") ?? throw new InvalidOperationException("Connection string missing Endpoint.");
        var deploymentId = parts.GetValueOrDefault("DeploymentId") ?? "gpt-4o-mini";
        var key = parts.GetValueOrDefault("Key");

        AzureOpenAIClient azureClient;
        if (!string.IsNullOrEmpty(key))
        {
            azureClient = new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(key));
        }
        else
        {
            azureClient = new AzureOpenAIClient(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential());
        }

        return azureClient.GetChatClient(deploymentId).AsIChatClient();
    }

    private static Dictionary<string, string> ParseConnectionString(string connStr)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var part in connStr.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var idx = part.IndexOf('=');
            if (idx > 0)
                result[part[..idx].Trim()] = part[(idx + 1)..].Trim();
        }
        return result;
    }
}

