public static IChatClient ResolveJudgeClient(IChatClient agentClient)
{
    var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
    if (!string.IsNullOrEmpty(judgeDeployment))
    {
        // Override: use a different deployment for the judge (e.g., when the
        // agent uses a reasoning model that rejects max_tokens).
        // Reuse the same endpoint/key but swap the deployment.
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var connStr = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connStr))
            throw new InvalidOperationException("EVAL_JUDGE_DEPLOYMENT_NAME set but ConnectionStrings:chat is missing.");

        var parts = connStr.Split(';', StringSplitOptions.RemoveEmptyEntries)
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        var endpoint = parts.GetValueOrDefault("Endpoint") ?? throw new InvalidOperationException("Missing Endpoint in connection string.");
        var key = parts.GetValueOrDefault("Key");

        Azure.AI.OpenAI.AzureOpenAIClient azureClient;
        if (!string.IsNullOrEmpty(key))
            azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key));
        else
            azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential());

        return azureClient.GetChatClient(judgeDeployment).AsIChatClient();
    }

    // Default: same client serves both agent and judge (MEAI caches both).
    return agentClient;
}

